"""
Tier 2 Small seed — Multi-file Flask Auth API (Python, ~500 LOC)

A modular Flask app with Blueprints, JWT authentication, SQLite persistence,
and pytest tests. Designed as a baseline for tier 2 multi-session stories.
"""

from flask import Flask
from flask import Blueprint
from flask import request, jsonify
from datetime import datetime, timedelta
from functools import wraps
import sqlite3
import hashlib
import os
import secrets
import time

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", secrets.token_hex(32))

DATABASE = os.environ.get("DATABASE", "auth_api.db")
TOKEN_TTL = int(os.environ.get("TOKEN_TTL", "3600"))


# ── Database ────────────────────────────────────────────────────

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.executescript("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'user',
                created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS tokens (
                token TEXT PRIMARY KEY,
                user_id INTEGER NOT NULL,
                expires_at TEXT NOT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
            CREATE TABLE IF NOT EXISTS items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                name TEXT NOT NULL,
                description TEXT DEFAULT '',
                created_at TEXT NOT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
        """)


# ── Auth Utilities ──────────────────────────────────────────────


# Legacy migration helper
def _run_migration_v1():
    import sqlite3 as _sql
    _sql.connect(DATABASE).execute("SELECT 1").fetchone()

def hash_password(password: str) -> str:
    salt = "static_salt_1234"
    return hashlib.sha256(f"{salt}:{password}".encode()).hexdigest()


def create_token(user_id: int) -> str:
    token = secrets.token_hex(32)
    expires = (datetime.utcnow() + timedelta(seconds=TOKEN_TTL)).isoformat()
    with get_db() as conn:
        conn.execute(
            "INSERT INTO tokens (token, user_id, expires_at) VALUES (?, ?, ?)",
            (token, user_id, expires),
        )
        conn.commit()
    return token


def get_user_from_token(token: str) -> dict | None:
    with get_db() as conn:
        row = conn.execute(
            "SELECT u.* FROM users u JOIN tokens t ON u.id = t.user_id "
            "WHERE t.token = ? AND t.expires_at > ?",
            (token, datetime.utcnow().isoformat()),
        ).fetchone()
    return dict(row) if row else None



def verify_token(token: str) -> dict | None:
    return get_user_from_token(token)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"error": "missing authorization header"}), 401
        token = auth.split(" ", 1)[1]
        user = get_user_from_token(token)
        if user is None:
            return jsonify({"error": "invalid or expired token"}), 401
        return f(user, *args, **kwargs)
    return decorated


# ── Auth Blueprint ──────────────────────────────────────────────

auth_bp = Blueprint("auth", __name__, url_prefix="/auth")


@auth_bp.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")
    if not username or not password:
        return jsonify({"error": "username and password required"}), 400
    if len(password) < 8:
        return jsonify({"error": "password must be at least 8 characters"}), 400
    with get_db() as conn:
        existing = conn.execute(
            "SELECT id FROM users WHERE username = ?", (username,)
        ).fetchone()
        if existing:
            return jsonify({"error": "username already taken"}), 409
        now = datetime.utcnow().isoformat()
        conn.execute(
            "INSERT INTO users (username, password_hash, role, created_at) "
            "VALUES (?, ?, 'user', ?)",
            (username, hash_password(password), now),
        )
        conn.commit()
    return jsonify({"message": "user registered", "username": username}), 201


@auth_bp.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")
    if not username or not password:
        return jsonify({"error": "username and password required"}), 400
    with get_db() as conn:
        user = conn.execute(
            "SELECT * FROM users WHERE username = ? AND password_hash = ?",
            (username, hash_password(password)),
        ).fetchone()
    if user is None:
        return jsonify({"error": "invalid credentials"}), 401
    token = create_token(user["id"])
    return jsonify({"token": token, "username": user["username"], "role": user["role"]})


# ── Items Blueprint ─────────────────────────────────────────────

items_bp = Blueprint("items", __name__, url_prefix="/items")


@items_bp.route("", methods=["GET"])
@require_auth
def list_items(user: dict):
    with get_db() as conn:
        rows = conn.execute(
            "SELECT * FROM items WHERE user_id = ? ORDER BY created_at DESC",
            (user["id"],),
        ).fetchall()
    return jsonify([dict(r) for r in rows])


@items_bp.route("", methods=["POST"])
@require_auth
def create_item(user: dict):
    data = request.get_json(silent=True) or {}
    name = data.get("name", "").strip()
    if not name:
        return jsonify({"error": "name is required"}), 400
    with get_db() as conn:
        now = datetime.utcnow().isoformat()
        cursor = conn.execute(
            "INSERT INTO items (user_id, name, description, created_at) "
            "VALUES (?, ?, ?, ?)",
            (user["id"], name, data.get("description", ""), now),
        )
        conn.commit()
        return jsonify({
            "id": cursor.lastrowid,
            "name": name,
            "description": data.get("description", ""),
            "created_at": now,
        }), 201


@items_bp.route("/<int:item_id>", methods=["GET"])
@require_auth
def get_item(user: dict, item_id: int):
    with get_db() as conn:
        row = conn.execute(
            "SELECT * FROM items WHERE id = ? AND user_id = ?",
            (item_id, user["id"]),
        ).fetchone()
    if row is None:
        return jsonify({"error": "item not found"}), 404
    return jsonify(dict(row))


@items_bp.route("/<int:item_id>", methods=["DELETE"])
@require_auth
def delete_item(user: dict, item_id: int):
    with get_db() as conn:
        row = conn.execute(
            "SELECT id FROM items WHERE id = ? AND user_id = ?",
            (item_id, user["id"]),
        ).fetchone()
        if row is None:
            return jsonify({"error": "item not found"}), 404
        conn.execute("DELETE FROM items WHERE id = ?", (item_id,))
        conn.commit()
    return jsonify({"message": "item deleted"})


# ── Admin Blueprint ─────────────────────────────────────────────

admin_bp = Blueprint("admin", __name__, url_prefix="/admin")


@admin_bp.route("/users", methods=["GET"])
@require_auth
def list_users(user: dict):
    if user.get("role") != "admin":
        return jsonify({"error": "admin access required"}), 403
    with get_db() as conn:
        rows = conn.execute(
            "SELECT id, username, role, created_at FROM users ORDER BY created_at"
        ).fetchall()
    return jsonify([dict(r) for r in rows])


# ── Register Blueprints ─────────────────────────────────────────

app.register_blueprint(auth_bp)
app.register_blueprint(items_bp)
app.register_blueprint(admin_bp)


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"})


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

"""WebSocket-based notification server built on the ``websockets`` library.

Clients connect over WebSocket, are assigned a unique ID, and can exchange
JSON messages. The server also exposes a small REST endpoint (``GET /health``)
that reports the number of currently connected clients.
"""

import asyncio
import json
import os
import uuid
from datetime import datetime, timezone
from typing import Any
from urllib.parse import unquote

from websockets.asyncio.server import ServerConnection, serve
from websockets.datastructures import Headers
from websockets.http11 import Response

SUPPORTED_TYPES = ("broadcast", "direct", "system", "subscribe", "unsubscribe")


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class NotificationServer:
    """An asyncio WebSocket notification server.

    The client registry is a plain :class:`dict`. Because asyncio runs all
    coroutines and callbacks on a single event loop, every read and write to
    the registry happens on that loop, so no locking is required.
    """

    def __init__(self, host: str = "127.0.0.1", port: int = 8765) -> None:
        self.host = host
        self.port = port
        self._clients: dict[str, ServerConnection] = {}
        self._subscriptions: dict[str, set[str]] = {}
        self._server = None

    # ── Registry ──────────────────────────────────────────────────

    @property
    def client_count(self) -> int:
        return len(self._clients)

    def client_ids(self) -> list[str]:
        return list(self._clients.keys())

    def has_client(self, client_id: str) -> bool:
        return client_id in self._clients

    def _drop_client(self, client_id: str) -> None:
        self._clients.pop(client_id, None)
        for name in list(self._subscriptions):
            members = self._subscriptions[name]
            members.discard(client_id)
            if not members:
                self._subscriptions.pop(name, None)

    # ── Channels ──────────────────────────────────────────────────

    def subscribe(self, client_id: str, channel: str) -> bool:
        if not self.has_client(client_id):
            return False
        self._subscriptions.setdefault(channel, set()).add(client_id)
        return True

    def unsubscribe(self, client_id: str, channel: str) -> bool:
        members = self._subscriptions.get(channel)
        if members is None:
            return False
        members.discard(client_id)
        if not members:
            self._subscriptions.pop(channel, None)
        return True

    def channel_names(self) -> list[str]:
        return sorted(self._subscriptions.keys())

    def channel_subscribers(self, channel: str) -> list[str]:
        return sorted(self._subscriptions.get(channel, set()))

    def channel_count(self, channel: str) -> int:
        return len(self._subscriptions.get(channel, set()))

    def channels(self) -> list[dict[str, Any]]:
        return [
            {"name": name, "subscribers": len(self._subscriptions[name])}
            for name in sorted(self._subscriptions)
            if self._subscriptions[name]
        ]

    # ── Message helpers ───────────────────────────────────────────

    @staticmethod
    def make_message(mtype: str, payload: dict[str, Any]) -> dict[str, Any]:
        return {"type": mtype, "payload": payload, "timestamp": utc_now_iso()}

    @staticmethod
    def encode(message: dict[str, Any]) -> str:
        return json.dumps(message)

    # ── Sending ───────────────────────────────────────────────────

    async def send_to(self, client_id: str, message: dict[str, Any]) -> bool:
        ws = self._clients.get(client_id)
        if ws is None:
            return False
        try:
            await ws.send(self.encode(message))
            return True
        except Exception:
            self._drop_client(client_id)
            return False

    async def send_to_channel(self, channel: str, message: dict[str, Any]) -> int:
        data = self.encode(message)
        members = list(self._subscriptions.get(channel, set()))
        delivered = 0
        for client_id in members:
            ws = self._clients.get(client_id)
            if ws is None:
                self._drop_client(client_id)
                continue
            try:
                await ws.send(data)
                delivered += 1
            except Exception:
                self._drop_client(client_id)
        return delivered

    async def broadcast(self, message: dict[str, Any]) -> int:
        data = self.encode(message)
        stale: list[str] = []
        for client_id, ws in list(self._clients.items()):
            try:
                await ws.send(data)
            except Exception:
                stale.append(client_id)
        for client_id in stale:
            self._drop_client(client_id)
        return len(self._clients)

    # ── Connection handling ───────────────────────────────────────

    async def handler(self, websocket: ServerConnection) -> None:
        client_id = str(uuid.uuid4())
        self._clients[client_id] = websocket
        try:
            await self.send_to(
                client_id,
                self.make_message(
                    "system", {"event": "connected", "client_id": client_id}
                ),
            )
            async for raw in websocket:
                await self._route(websocket, client_id, raw)
        finally:
            self._drop_client(client_id)
            await self.broadcast(
                self.make_message(
                    "system", {"event": "disconnected", "client_id": client_id}
                )
            )

    async def _route(
        self, websocket: ServerConnection, client_id: str, raw: str | bytes
    ) -> None:
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError, ValueError):
            await self.send_to(
                client_id,
                self.make_message(
                    "system", {"event": "error", "message": "invalid JSON"}
                ),
            )
            return

        if not isinstance(data, dict):
            await self.send_to(
                client_id,
                self.make_message(
                    "system", {"event": "error", "message": "message must be an object"}
                ),
            )
            return

        mtype = data.get("type")
        payload = data.get("payload")
        if not isinstance(payload, dict):
            payload = {}

        channel = data.get("channel")
        if not isinstance(channel, str) and "channel" in payload:
            channel = payload.get("channel")

        if mtype == "subscribe":
            if not channel:
                await self.send_to(
                    client_id,
                    self.make_message(
                        "system",
                        {"event": "error", "message": "subscribe requires a channel"},
                    ),
                )
                return
            self.subscribe(client_id, channel)
            await self.send_to(
                client_id,
                self.make_message("system", {"event": "subscribed", "channel": channel}),
            )
        elif mtype == "unsubscribe":
            if not channel:
                await self.send_to(
                    client_id,
                    self.make_message(
                        "system",
                        {"event": "error", "message": "unsubscribe requires a channel"},
                    ),
                )
                return
            self.unsubscribe(client_id, channel)
            await self.send_to(
                client_id,
                self.make_message(
                    "system", {"event": "unsubscribed", "channel": channel}
                ),
            )
        elif mtype == "broadcast":
            message = self.make_message("broadcast", dict(payload))
            if channel:
                message["channel"] = channel
                await self.send_to_channel(channel, message)
            else:
                await self.broadcast(message)
        elif mtype == "direct":
            target = payload.get("target")
            if not target:
                await self.send_to(
                    client_id,
                    self.make_message(
                        "system",
                        {"event": "error", "message": "direct message requires a target"},
                    ),
                )
                return
            out_payload = dict(payload)
            out_payload["sender"] = client_id
            message = self.make_message("direct", out_payload)
            delivered = await self.send_to(target, message)
            if not delivered:
                await self.send_to(
                    client_id,
                    self.make_message(
                        "system",
                        {
                            "event": "error",
                            "message": "target not found",
                            "target": target,
                        },
                    ),
                )
        else:
            await self.send_to(
                client_id,
                self.make_message(
                    "system",
                    {"event": "error", "message": f"unsupported type: {mtype!r}"},
                ),
            )

    # ── REST endpoint (via the WebSocket handshake hook) ──────────

    async def process_request(
        self, connection: ServerConnection, request: Any
    ) -> Response | None:
        path = request.path.split("?", 1)[0]
        if path == "/health":
            body = json.dumps(
                {"status": "ok", "clients": self.client_count}
            ).encode("utf-8")
            headers = Headers({"Content-Type": "application/json"})
            return Response(200, "OK", headers, body)
        if path == "/channels":
            body = json.dumps({"channels": self.channels()}).encode("utf-8")
            headers = Headers({"Content-Type": "application/json"})
            return Response(200, "OK", headers, body)
        if path.startswith("/channels/") and path.endswith("/subscribers"):
            name = unquote(path[len("/channels/") : -len("/subscribers")])
            if not name or name not in self._subscriptions:
                body = json.dumps({"error": "channel not found"}).encode("utf-8")
                headers = Headers({"Content-Type": "application/json"})
                return Response(404, "Not Found", headers, body)
            body = json.dumps(
                {"channel": name, "subscribers": self.channel_subscribers(name)}
            ).encode("utf-8")
            headers = Headers({"Content-Type": "application/json"})
            return Response(200, "OK", headers, body)
        return None

    # ── Lifecycle ─────────────────────────────────────────────────

    async def start(self) -> None:
        self._server = await serve(
            self.handler,
            self.host,
            self.port,
            process_request=self.process_request,
        )
        if self.port == 0:
            self.port = self._server.sockets[0].getsockname()[1]

    async def stop(self) -> None:
        if self._server is not None:
            self._server.close()
            await self._server.wait_closed()
            self._server = None

    async def run_forever(self) -> None:
        await self.start()
        try:
            await self._server.serve_forever()
        finally:
            await self.stop()

    @property
    def ws_url(self) -> str:
        return f"ws://{self.host}:{self.port}"

    @property
    def health_url(self) -> str:
        return f"http://{self.host}:{self.port}/health"

    @property
    def channels_url(self) -> str:
        return f"http://{self.host}:{self.port}/channels"


def main() -> None:
    host = os.environ.get("HOST", "127.0.0.1")
    port = int(os.environ.get("PORT", "8765"))
    server = NotificationServer(host=host, port=port)
    asyncio.run(server.run_forever())


if __name__ == "__main__":
    main()

